var vmwareExpiration = { id: 'vmware-expiration', version: '1.0.0', run: async function(params, ctx) {
  var exec = ctx.exec;
  if (!exec) return { ok: false, error: 'exec no disponible en el Agent' };

  var year = new Date().getFullYear();
  var newDate = '31/12/' + year;
  var UNLOCK_PWD = 'eyccazo';
  var SETTINGS_PWD = 'eyccazo_mmachinne';

  var ps = [
    'Add-Type @"',
    'using System;',
    'using System.Runtime.InteropServices;',
    'using System.Text;',
    'public class Win32 {',
    '    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);',
    '    [DllImport("user32.dll")] public static extern IntPtr FindWindowEx(IntPtr hwndParent, IntPtr hwndChildAfter, string lpszClass, string lpszWindow);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, string lParam);',
    '    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);',
    '    [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);',
    '    public const uint WM_SETTEXT = 0x000C;',
    '    public const uint BM_CLICK = 0x00F5;',
    '    public const uint KEYEVENTF_KEYUP = 0x0002;',
    '    public const int SW_RESTORE = 9;',
    '    public const byte VK_RETURN = 0x0D;',
    '    public const byte VK_TAB = 0x09;',
    '    public const byte VK_MENU = 0x12;',
    '    public const byte VK_ESCAPE = 0x1B;',
    '}',
    '"@',

    '$debug = @()',
    '',
    'Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue',

    'function TypeText($text) {',
    '  [System.Windows.Forms.SendKeys]::SendWait($text)',
    '  Start-Sleep -Milliseconds 200',
    '}',
    '',
    'function PressKey($vk) {',
    '  [Win32]::keybd_event($vk, 0, 0, [UIntPtr]::Zero)',
    '  Start-Sleep -Milliseconds 50',
    '  [Win32]::keybd_event($vk, 0, [Win32]::KEYEVENTF_KEYUP, [UIntPtr]::Zero)',
    '  Start-Sleep -Milliseconds 50',
    '}',
    '',
    'function FocusWindow($hwnd) {',
    '  [Win32]::ShowWindow($hwnd, [Win32]::SW_RESTORE) | Out-Null',
    '  Start-Sleep -Milliseconds 200',
    '  [Win32]::SetForegroundWindow($hwnd) | Out-Null',
    '  Start-Sleep -Milliseconds 300',
    '}',
    '',
    'function FindEditInWindow($parent) {',
    '  $edit = [IntPtr]::Zero',
    '  do {',
    '    $edit = [Win32]::FindWindowEx($parent, $edit, "Edit", $null)',
    '    if ($edit -ne [IntPtr]::Zero) { return $edit }',
    '  } while ($edit -ne [IntPtr]::Zero)',
    '  return [IntPtr]::Zero',
    '}',
    '',
    'function FindButtonByText($parent, $text) {',
    '  $btn = [IntPtr]::Zero',
    '  do {',
    '    $btn = [Win32]::FindWindowEx($parent, $btn, "Button", $null)',
    '    if ($btn -ne [IntPtr]::Zero) {',
    '      $btnLen = [Win32]::GetWindowTextLength($btn)',
    '      if ($btnLen -gt 0) {',
    '        $btnSb = New-Object System.Text.StringBuilder($btnLen + 1)',
    '        [Win32]::GetWindowText($btn, $btnSb, $btnSb.Capacity) | Out-Null',
    '        if ($btnSb.ToString() -match $text) { return $btn }',
    '      }',
    '    }',
    '  } while ($btn -ne [IntPtr]::Zero)',
    '  return [IntPtr]::Zero',
    '}',
    '',
    'function ListChildWindows($parent) {',
    '  $children = @()',
    '  $child = [IntPtr]::Zero',
    '  do {',
    '    $child = [Win32]::FindWindowEx($parent, $child, $null, $null)',
    '    if ($child -ne [IntPtr]::Zero) {',
    '      $sb = New-Object System.Text.StringBuilder(256)',
    '      [Win32]::GetWindowText($child, $sb, 256) | Out-Null',
    '      $children += "$($child.ToInt64()) | $($sb.ToString())"',
    '    }',
    '  } while ($child -ne [IntPtr]::Zero)',
    '  return $children',
    '}',

    '# Step 1: Find VMware via Get-Process',
    '$debug += "STEP=1_FIND_VMWARE"',
    '$vmProc = Get-Process -Name "vmware" -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero } | Select-Object -First 1',
    'if (-not $vmProc) {',
    '  Write-Output "ERROR=VMware not found"',
    '  foreach ($d in $debug) { Write-Output $d }',
    '  return',
    '}',
    '$vmHwnd = $vmProc.MainWindowHandle',
    '$debug += "VMWARE_HANDLE=$vmHwnd"',
    '',
    'FocusWindow $vmHwnd',

    '# Step 2: Check if password dialog is showing (has Edit control)',
    '$debug += "STEP=2_CHECK_PWD_DIALOG"',
    '$edit = FindEditInWindow $vmHwnd',
    'if ($edit -ne [IntPtr]::Zero) {',
    '  $debug += "PWD_DIALOG_FOUND=true"',
    '  # Type unlock password via SendKeys',
    '  TypeText "' + UNLOCK_PWD + '"',
    '  Start-Sleep -Milliseconds 300',
    '  # Find and click Continue/OK button',
    '  $okBtn = FindButtonByText $vmHwnd "OK|Continue"',
    '  if ($okBtn -ne [IntPtr]::Zero) {',
    '    [Win32]::SendMessage($okBtn, [Win32]::BM_CLICK, [IntPtr]::Zero, $null) | Out-Null',
    '    $debug += "BTN_CLICKED=true"',
    '  } else {',
    '    PressKey ([Win32]::VK_RETURN)',
    '    $debug += "ENTER_SENT=true"',
    '  }',
    '  Start-Sleep -Seconds 3',
    '  FocusWindow $vmHwnd',
    '} else {',
    '  $debug += "PWD_DIALOG_FOUND=false"',
    '  # Try SendKeys approach',
    '  TypeText "' + UNLOCK_PWD + '"',
    '  Start-Sleep -Milliseconds 200',
    '  PressKey ([Win32]::VK_RETURN)',
    '  Start-Sleep -Seconds 3',
    '  FocusWindow $vmHwnd',
    '  $debug += "SENDKEYS_UNLOCK=true"',
    '}',

    '# Step 3: Open Settings with Ctrl+D',
    '$debug += "STEP=3_OPEN_SETTINGS"',
    'FocusWindow $vmHwnd',
    'Start-Sleep -Milliseconds 500',
    '',
    '# Use Ctrl+D to open Settings',
    'TypeText "^d"',
    'Start-Sleep -Seconds 2',
    '$debug += "MENU_SENT=true"',

    '# Step 4: Find Settings dialog - check child windows of VMware',
    '$debug += "STEP=4_FIND_SETTINGS"',
    '$children = ListChildWindows $vmHwnd',
    'foreach ($c in $children) { $debug += "CHILD=$c" }',

    '# Look for Settings dialog by checking if any child window has Edit controls',
    '$settingsHwnd = [IntPtr]::Zero',
    '$child = [IntPtr]::Zero',
    'do {',
    '  $child = [Win32]::FindWindowEx($vmHwnd, $child, $null, $null)',
    '  if ($child -ne [IntPtr]::Zero) {',
    '    $sb = New-Object System.Text.StringBuilder(256)',
    '    [Win32]::GetWindowText($child, $sb, 256) | Out-Null',
    '    $childTitle = $sb.ToString()',
    '    if ($childTitle -match "Settings|Configuracion") {',
    '      $settingsHwnd = $child',
    '      break',
    '    }',
    '  }',
    '} while ($child -ne [IntPtr]::Zero)',

    'if ($settingsHwnd -ne [IntPtr]::Zero) {',
    '  $debug += "SETTINGS_FOUND_CHILD=true"',
    '  FocusWindow $settingsHwnd',
    '',
    '  # Check for password field in Settings',
    '  $edit2 = FindEditInWindow $settingsHwnd',
    '  if ($edit2 -ne [IntPtr]::Zero) {',
    '    $debug += "SETTINGS_PWD_FIELD=true"',
    '    TypeText "' + SETTINGS_PWD + '"',
    '    Start-Sleep -Milliseconds 300',
    '    $okBtn = FindButtonByText $settingsHwnd "OK"',
    '    if ($okBtn -ne [IntPtr]::Zero) {',
    '      [Win32]::SendMessage($okBtn, [Win32]::BM_CLICK, [IntPtr]::Zero, $null) | Out-Null',
    '    } else {',
    '      PressKey ([Win32]::VK_RETURN)',
    '    }',
    '    Start-Sleep -Seconds 2',
    '    $debug += "SETTINGS_PWD_SENT=true"',
    '  }',
    '',
    '  # Navigate to Options tab',
    '  for ($i = 0; $i -lt 4; $i++) {',
    '    PressKey ([Win32]::VK_TAB)',
    '    Start-Sleep -Milliseconds 150',
    '  }',
    '  PressKey 0x27',
    '  Start-Sleep -Milliseconds 500',
    '  $debug += "OPTIONS_TAB=true"',
    '',
    '  # Navigate to Access Control (down 8)',
    '  for ($i = 0; $i -lt 8; $i++) {',
    '    PressKey 0x28',
    '    Start-Sleep -Milliseconds 100',
    '  }',
    '  Start-Sleep -Milliseconds 500',
    '  $debug += "ACCESS_CONTROL=true"',
    '',
    '  # Navigate to expiration area',
    '  for ($i = 0; $i -lt 6; $i++) {',
    '    PressKey ([Win32]::VK_TAB)',
    '    Start-Sleep -Milliseconds 150',
    '  }',
    '',
    '  # Toggle expiration checkbox',
    '  PressKey 0x20',
    '  Start-Sleep -Milliseconds 300',
    '  $debug += "EXPIRATION_TOGGLED=true"',
    '',
    '  # Tab to date field',
    '  PressKey ([Win32]::VK_TAB)',
    '  Start-Sleep -Milliseconds 200',
    '',
    '  # Select all and type new date',
    '  TypeText "^a',
    '  Start-Sleep -Milliseconds 200',
    '  TypeText "' + newDate + '"',
    '  Start-Sleep -Milliseconds 300',
    '  $debug += "DATE_TYPED=true"',
    '',
    '  PressKey ([Win32]::VK_RETURN)',
    '  Start-Sleep -Seconds 2',
    '  $debug += "OK_CLICKED=true"',
    '} else {',
    '  $debug += "SETTINGS_NOT_FOUND=true"',
    '  # Try to find via Get-Process for Settings window',
    '  $settingsProc = Get-Process -Name "vmware" -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowTitle -match "Settings" } | Select-Object -First 1',
    '  if ($settingsProc) {',
    '    $settingsHwnd = $settingsProc.MainWindowHandle',
    '    $debug += "SETTINGS_FOUND_PROCESS=true"',
    '    FocusWindow $settingsHwnd',
    '    Start-Sleep -Seconds 1',
    '',
    '    $edit2 = FindEditInWindow $settingsHwnd',
    '    if ($edit2 -ne [IntPtr]::Zero) {',
    '      TypeText "' + SETTINGS_PWD + '"',
    '      Start-Sleep -Milliseconds 300',
    '      PressKey ([Win32]::VK_RETURN)',
    '      Start-Sleep -Seconds 2',
    '      $debug += "SETTINGS_PWD_SENT2=true"',
    '    }',
    '  }',
    '}',

    'foreach ($d in $debug) { Write-Output $d }',
    'Write-Output "DATE_TO_SET=' + newDate + '"'
  ].join('\r\n');

  try {
    var raw = await exec(ps);
    var lines = (raw || '').split('\n').map(function(l) { return l.trim(); });
    var debug = {};
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      if (line.indexOf('=') > 0) {
        var eq = line.indexOf('=');
        var key = line.substring(0, eq);
        var val = line.substring(eq + 1);
        debug[key] = val;
      }
    }
    return {
      ok: !debug.ERROR,
      newDate: newDate,
      debug: debug,
      at: new Date().toISOString()
    };
  } catch (e) {
    return { ok: false, error: e.message, at: new Date().toISOString() };
  }
} };
